import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第五卷 答案 · 第103章 被退","description":"","frontmatter":{},"headers":[],"relativePath":"第103章_被退.md","filePath":"第103章_被退.md"}'),r={name:"第103章_被退.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第五卷-答案-·-第103章-被退" tabindex="-1">第五卷 答案 · 第103章 被退 <a class="header-anchor" href="#第五卷-答案-·-第103章-被退" aria-label="Permalink to &quot;第五卷 答案 · 第103章 被退&quot;">​</a></h1><p>后街夜市的风是热的，混着油烟和汗味，贴在脸上黏黏的。</p><p>我到的时候，周野已经占好南雾老乡小桌，桌上摆三只倒扣茶杯。顾远坐对面，见我来抬头一笑。</p><p>“就差你了，沈聿。”</p><p>塑料凳子还留余温。周野熟门熟路喊，炒面三份，糖水三碗，都多料。</p><p>灯管嗞嗞响，隔壁桌啤酒沫落地，被拖鞋带出湿印。夜市吵挤烫，像一直滚的水。</p><p>顾远给我倒了杯热茶。</p><p>“脸色有点沉，赶稿熬的？”</p><p>我摇头，从裤兜摸出一个小信封，放在桌中间。信封口开着，露出一截红绳，颜色很正，在灯下有点晃眼。</p><p>周野一眼看到，筷子一顿。</p><p>“这绳头眼熟，你编的平安结，咋又回来了？”</p><p>我嗯了一声，指腹摩挲着信封。纸面发潮，被手心汗浸软了。</p><p>“退回来了。”</p><p>顾远愣住。</p><p>“江苒退的？”</p><p>我点头，喝了口茶。茶水很烫，舌尖发麻，却觉得正好。喉咙像堵着团棉花，需要这点烫来化开。</p><p>远处铁板刺啦一声，炒面下锅，香味飘来。我看白雾，心里平静。要讲散了的感情，也就是需要这样一夜，一桌，两老乡，一碗糖水。</p><p>“讲讲吧。”周野放低声音。“我们还没好好听过你们的事。”</p><p>我捧着茶杯暖手，笑了笑，笑得有点干。</p><p>故事很简单，放在雾山大学里一抓一大把。</p><p>我和江苒做过两年同桌。我话少，她话多。她爱在课间听磁带，用的旧随身听，倒带会咔咔响。有次她忘带电池，趴桌上叹气。我第二天就把自己的机器翻出来借她。</p><p>那台机器是奶奶买的。奶奶说，老街夜里风大，有个声儿陪着，睡得稳。</p><p>江苒很爱惜，用完都会把磁带倒回开头。她说磁带好，听得到头，等得到尾，不像有些话，说一半就没了。</p><p>后来我在雾山大学，她在南州外院，中间隔着一百多公里和一班不通的客车。她叠纸星星，用便宜彩纸，叠满一罐送我，说保平安。我放床头，太阳照进来满罐光。</p><p>平安结是我跟奶奶学的。她说能压惊守人。我编很久，拆了编编了拆。编好那晚去找她，把结放她手心，还带着体温。</p><p>她捏着看了很久，眼圈红，轻声说，沈聿，这份心太重，我先收下，好好放着。</p><p>我以为收下就是收下了。</p><p>顾远凑近问，那咋又退了？</p><p>正说着，炒面上来了。老板把盘子墩在桌上，热气糊了我一脸。我摘眼镜擦了擦。</p><p>“没吵。寒假她回南雾，我在老街口把结递过去，走之前她把信封退回来，结叠得整齐。她说心里很乱，怕辜负心意，先还给我，以后再说。”</p><p>以后是啥，她没说，我没问。有些话问出口就变味了。</p><p>周野没接话，大口吃面。我吃一口，心里空空漏风。</p><p>糖水上了，白果薏米熬得稠。我捧碗，暖意传到小臂，才活过来。</p><p>“你就接了？”顾远有点急。“没多说？”</p><p>我看碗里晃动的糖水，轻声说，她眼里全是为难，多说就是逼她。心乱时拿着别人心意，负担重，我不想让她为难。</p><p>说完我愣了下，原来难过到份上，人会讲道理，还讲得挺像样。</p><p>周野叹气拍我肩，力道大，拍得我一晃。</p><p>“你从小就这样，跟奶奶住久了，啥都藏心里。”</p><p>提到奶奶，心又沉下去。</p><p>那本小说本打算这个月送出去。讲老街，讲半留守孩子和守屋老人。我想让江苒先看，看看我长大的地方。</p><p>可她阿婆病倒了。老街来电话，说是起夜晕了一下，现在躺在床上，粥也喝得少。我打过去接的是江苒，她哑着声说没事，让我读书，别惦记。</p><p>小说就暂缓了。这时送出去像急着要评价，我不想。</p><p>顾远添茶问，叔婶还外面吗？</p><p>我点头。他们常年在外，我从小跟奶奶住老街，算半留守。房子旧，青石路雨天长苔。奶奶早起熬粥，晚上留盏灯。随身听第一盘磁带是奶奶买的，全是戏，她跟着哼，我放学远远听见，心就定了。</p><p>以前很少提这些。今晚在老乡桌上说出来，倒也没多难。</p><p>我把信封打开，倒出平安结放掌心。红绳软，结紧，纹路清，底下两根绳头光秃秃留着，本要穿珠子，没来得及。</p><p>周野凑来看，啧一声。</p><p>“手艺真不赖，退了可惜。”</p><p>“不可惜。”我说。“送出去过，就不算白费。她认真收过，这就够了。”</p><p>鼻子发酸，我低头喝糖水。甜压下来，酸才散。</p><p>顾远问，那接下来咋办，一直放信封？</p><p>我摇头，咋舍得。</p><p>想起奶奶教编结的午后。她坐竹椅，手把手教，绳头压住，圈绕匀，收尾拉紧。她说好事慢慢编，急不得。我觉得绳子有温度。</p><p>我把随身听拿出来。旧机器跟我多年，边角磨白。我把绳头绕过侧面挂环，打个小结拉紧。</p><p>红绳衬灰黑机身，夜风一吹轻晃，像小簇火苗。</p><p>周野看呆，问这算啥，给自己上课？</p><p>我把机器立桌上。</p><p>“算释然第一课。”我说。“她还我，我就留着。系这里，听歌能看见，提醒自己好好生活，别辜负编它的那个晚上，也别辜负奶奶的手艺。”</p><p>顾远笑，端糖水碗碰我一下，清脆一声。</p><p>“有你的味儿。”</p><p>我们低头吃面。面有点凉，不如刚上香，可都吃得认真，像把热气吃进肚子。</p><p>夜市人少了，老板收凳子，铁盆脆响。雾从街口漫来，带着凉。</p><p>我把随身听收好，耳机线绕齐，绳结贴机身，装进口袋还能摸到那点软。</p><p>正要起身，手机在桌上震亮。</p><p>是老街发来的消息，那个存了多年的号码在最上，后面跟了句很短的话。</p><p>我盯着那行字，心跳忽快，手指停半空，没点开。</p>',66)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
